// Test-only module resolution for @flybot/timeline (ThinkFlowLab/FlyBot#34).
// - `ds-bot` resolves to the FlyBot core checkout, the way a DSH profile supplies the peer:
//   FLYBOT_CORE, else the repo-root `core/` (pristine ds-bot/ + patches/ds-bot/, generated by
//   scripts/ds-bot-patches.mjs). Never `ds-bot/`: that is unpatched upstream, with no flybot API.
// - `@deepseek-ai/*` imported from inside that core resolves from a DeepSeek Harness:
//   DSH_HARNESS, else <core>/dev/harness (`npm run harness` in the core).
// Timeline's own code never imports ds-bot; only the host tests do, by its public entry.
import { existsSync } from 'node:fs'
import { registerHooks } from 'node:module'
import { join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

const repo = resolve(import.meta.dirname, '../../..')
const core = process.env.FLYBOT_CORE
  ? resolve(process.env.FLYBOT_CORE)
  : join(repo, 'core')
if (!existsSync(join(core, 'package.json'))) throw new Error(`@flybot/timeline tests: no FlyBot core at ${core} (set FLYBOT_CORE)`)
const harness = process.env.DSH_HARNESS ?? join(core, 'dev', 'harness')
process.env.DSH_HARNESS = harness
process.env.FLYBOT_CORE = core // tests read interface-layer files (flybot-registry.js) from here
const base = resolve(harness, 'packages/bundle/base/package.json')
const anchor = pathToFileURL(existsSync(base) ? base : resolve(harness, 'package.json')).href
const coreUrl = `${pathToFileURL(core).href}/`
const entry = pathToFileURL(join(core, 'index.js')).href

registerHooks({
  resolve(specifier, context, nextResolve) {
    if (specifier === 'ds-bot') return { url: entry, format: 'module', shortCircuit: true }
    if (specifier.startsWith('@deepseek-ai/') && context.parentURL?.startsWith(coreUrl)) {
      return nextResolve(specifier, { ...context, parentURL: anchor })
    }
    return nextResolve(specifier, context)
  },
})
